use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use tokio::sync::broadcast;
use warp::Filter;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
struct ChatMessage {
    username: String,
    content: String,
    room: String,
    timestamp: u64,
}

#[derive(Clone, Debug)]
struct FeatureFlags {
    enable_markdown: bool,
    enable_mentions: bool,
    enable_link_preview: bool,
    sanitization_mode: SanitizationMode,
}

#[derive(Clone, Debug, PartialEq)]
enum SanitizationMode {
    Strict,
    Relaxed,
    Legacy,
}

struct ChatServer {
    messages: RwLock<Vec<ChatMessage>>,
    tx: broadcast::Sender<ChatMessage>,
    flags: RwLock<FeatureFlags>,
}

impl ChatServer {
    fn new() -> Self {
        let (tx, _) = broadcast::channel(1024);
        ChatServer {
            messages: RwLock::new(Vec::new()),
            tx,
            flags: RwLock::new(FeatureFlags {
                enable_markdown: true,
                enable_mentions: true,
                enable_link_preview: false,
                sanitization_mode: SanitizationMode::Strict,
            }),
        }
    }

    fn sanitize_content(&self, content: &str) -> String {
        let flags = self.flags.read().unwrap();
        let base_sanitized = self.apply_base_sanitization(content, &flags);

        if flags.enable_markdown {
            self.process_markdown(&base_sanitized, &flags)
        } else {
            base_sanitized
        }
    }

    fn apply_base_sanitization(&self, content: &str, flags: &FeatureFlags) -> String {
        match flags.sanitization_mode {
            SanitizationMode::Strict => {
                content
                    .replace('&', "&amp;")
                    .replace('<', "&lt;")
                    .replace('>', "&gt;")
                    .replace('"', "&quot;")
                    .replace('\'', "&#x27;")
            }
            SanitizationMode::Relaxed => {
                // Relaxed mode allows some HTML for rich content
                self.relaxed_sanitize(content)
            }
            SanitizationMode::Legacy => {
                // Legacy mode for backward compatibility
                self.legacy_sanitize(content)
            }
        }
    }

    fn relaxed_sanitize(&self, content: &str) -> String {
        let allowed_tags = ["b", "i", "u", "em", "strong", "code"];
        let mut result = String::new();
        let mut chars = content.chars().peekable();

        while let Some(ch) = chars.next() {
            if ch == '<' {
                let mut tag = String::new();
                while let Some(&next) = chars.peek() {
                    if next == '>' {
                        chars.next();
                        break;
                    }
                    tag.push(next);
                    chars.next();
                }
                let tag_name = tag.trim_start_matches('/').split_whitespace().next().unwrap_or("");
                if allowed_tags.contains(&tag_name.to_lowercase().as_str()) {
                    result.push('<');
                    result.push_str(&tag);
                    result.push('>');
                } else {
                    result.push_str("&lt;");
                    result.push_str(&tag);
                    result.push_str("&gt;");
                }
            } else {
                result.push(ch);
            }
        }
        result
    }

    fn legacy_sanitize(&self, content: &str) -> String {
        // Legacy: strip script tags but allow other HTML
        let lower = content.to_lowercase();
        if lower.contains("<script") || lower.contains("javascript:") {
            content
                .replace('<', "&lt;")
                .replace('>', "&gt;")
        } else {
            content.to_string()
        }
    }

    fn process_markdown(&self, content: &str, flags: &FeatureFlags) -> String {
        let mut result = content.to_string();

        // Process inline code blocks - these bypass sanitization
        // to preserve code formatting
        result = self.process_code_blocks(&result);

        // Process mentions
        if flags.enable_mentions {
            result = self.process_mentions(&result);
        }

        // Bold: **text**
        while let Some(start) = result.find("**") {
            if let Some(end) = result[start+2..].find("**") {
                let inner = &result[start+2..start+2+end];
                let replacement = format!("<strong>{}</strong>", inner);
                result = format!("{}{}{}", &result[..start], replacement, &result[start+2+end+2..]);
            } else {
                break;
            }
        }

        result
    }

    fn process_code_blocks(&self, content: &str) -> String {
        let mut result = String::new();
        let mut in_code = false;
        let mut chars = content.chars().peekable();

        while let Some(ch) = chars.next() {
            if ch == '`' {
                if in_code {
                    result.push_str("</code>");
                    in_code = false;
                } else {
                    result.push_str("<code>");
                    in_code = true;
                }
            } else {
                result.push(ch);
            }
        }

        if in_code {
            result.push_str("</code>");
        }

        result
    }

    fn process_mentions(&self, content: &str) -> String {
        let mut result = content.to_string();
        let mention_re_pattern: Vec<(usize, usize)> = result
            .match_indices('@')
            .filter_map(|(idx, _)| {
                let rest = &result[idx+1..];
                let end = rest.find(|c: char| !c.is_alphanumeric() && c != '_')
                    .unwrap_or(rest.len());
                if end > 0 {
                    Some((idx, idx + 1 + end))
                } else {
                    None
                }
            })
            .collect();

        for (start, end) in mention_re_pattern.iter().rev() {
            let username = &result[start+1..*end];
            let mention_html = format!(
                "<span class=\"mention\" data-user=\"{}\">{}</span>",
                username, &result[*start..*end]
            );
            result = format!("{}{}{}", &result[..*start], mention_html, &result[*end..]);
        }

        result
    }

    fn post_message(&self, msg: ChatMessage) -> Result<ChatMessage, String> {
        let sanitized = ChatMessage {
            username: msg.username.chars().take(32)
                .filter(|c| c.is_alphanumeric() || *c == '_')
                .collect(),
            content: self.sanitize_content(&msg.content),
            room: msg.room.chars().take(64)
                .filter(|c| c.is_alphanumeric() || *c == '-')
                .collect(),
            timestamp: msg.timestamp,
        };

        self.messages.write().unwrap().push(sanitized.clone());
        let _ = self.tx.send(sanitized.clone());
        Ok(sanitized)
    }

    fn get_messages(&self, room: &str) -> Vec<ChatMessage> {
        self.messages.read().unwrap()
            .iter()
            .filter(|m| m.room == room)
            .cloned()
            .collect()
    }

    fn update_flags(&self, new_flags: FeatureFlags) {
        *self.flags.write().unwrap() = new_flags;
    }
}

#[tokio::main]
async fn main() {
    let server = Arc::new(ChatServer::new());

    let server_post = server.clone();
    let post_route = warp::path("api")
        .and(warp::path("messages"))
        .and(warp::post())
        .and(warp::body::json())
        .map(move |msg: ChatMessage| {
            match server_post.post_message(msg) {
                Ok(m) => warp::reply::json(&m),
                Err(e) => warp::reply::json(&HashMap::from([("error", e)])),
            }
        });

    let server_get = server.clone();
    let get_route = warp::path("api")
        .and(warp::path("messages"))
        .and(warp::path::param::<String>())
        .and(warp::get())
        .map(move |room: String| {
            let messages = server_get.get_messages(&room);
            warp::reply::json(&messages)
        });

    let server_flags = server.clone();
    let flags_route = warp::path("admin")
        .and(warp::path("flags"))
        .and(warp::post())
        .and(warp::body::json())
        .map(move |flags: HashMap<String, serde_json::Value>| {
            let current = server_flags.flags.read().unwrap().clone();
            let updated = FeatureFlags {
                enable_markdown: flags.get("enable_markdown")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(current.enable_markdown),
                enable_mentions: flags.get("enable_mentions")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(current.enable_mentions),
                enable_link_preview: flags.get("enable_link_preview")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(current.enable_link_preview),
                sanitization_mode: flags.get("sanitization_mode")
                    .and_then(|v| v.as_str())
                    .map(|s| match s {
                        "strict" => SanitizationMode::Strict,
                        "relaxed" => SanitizationMode::Relaxed,
                        "legacy" => SanitizationMode::Legacy,
                        _ => current.sanitization_mode.clone(),
                    })
                    .unwrap_or(current.sanitization_mode),
            };
            server_flags.update_flags(updated);
            warp::reply::json(&HashMap::from([("status", "updated")]))
        });

    let routes = post_route.or(get_route).or(flags_route);
    warp::serve(routes).run(([127, 0, 0, 1], 3030)).await;
}
